(* [comment removed for export] *)
Lemma cm_segC : forall (pcv rax sp gp tp t0 t1 t2 s0 s1 a0 a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6 : word)
    (rav hv : word) (F : bvmap 5 word) fc (m : mem) (lo : Z) (j4 : list byte),
  (pcv = Z_to_bv 64 P_A_CM_RET \/ pcv = ret_pc (Z_to_bv 64 P_A_CM_RET)) ->
  rw_cells asegs m (bv_unsigned sp + -16) [CB 4 j4; C4 hv; C8 rav] ->
  stk asegs m lo (bv_unsigned sp + -16) -> lo + 16 <= bv_unsigned sp -> aceil <= lo ->
  bv_unsigned rav mod 2 = 0 -> mem_inv asegs m ->
  evt asegs (fun ms' => ms' = MS (mkR rav sp gp tp t0 t1 t2 s0 s1 a0 a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
                                 F (ret_pc rav) fc None m (seg_rom asegs)
                        /\ stk asegs m lo (bv_unsigned sp))
    (MS (mkR rax (Z_to_bv 64 (bv_unsigned sp + -16)) gp tp t0 t1 t2 s0 s1 a0 a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
